import java.util.*;
import java.io.*;

class Main {
    static final int MAXN = 256;
    static final int MAXT = 64;
    static final int MAXE = MAXN * MAXN;
    static final int INF = 1000000000;

    static class Edge {
        int u, v, f, c, nx;
        Edge() {}
        Edge(int u, int v, int f, int c, int nx) {
            this.u = u; this.v = v; this.f = f; this.c = c; this.nx = nx;
        }
    }

    static class Dinic {
        Edge[] e = new Edge[MAXE];
        int n, m, src, dst, head[] = new int[MAXN], work[] = new int[MAXN], d[] = new int[MAXN];

        boolean _bfs() {
            Queue<Integer> q = new LinkedList<>();
            Arrays.fill(d, -1);
            q.offer(src);
            d[src] = 0;
            while(!q.isEmpty()) {
                int k = q.poll();
                for(int i = head[k]; i != -1; i = e[i].nx) {
                    if(e[i].f < e[i].c && d[e[i].v] == -1) {
                        d[e[i].v] = d[k] + 1;
                        q.offer(e[i].v);
                    }
                }
            }
            return d[dst] != -1;
        }

        int _dfs(int u, int f) {
            if(u == dst)
                return f;
            int minf;
            for(int i = work[u]; i != -1; i = e[i].nx) {
                if(e[i].f < e[i].c && d[e[i].v] == d[u] + 1) {
                    minf = _dfs(e[i].v, Math.min(f, e[i].c - e[i].f));
                    if(minf > 0) {
                        e[i].f += minf;
                        e[i ^ 1].f -= minf;
                        return minf;
                    }
                }
            }
            return 0;
        }

        void init(int n, int src, int dst) {
            this.n = n;
            this.src = src;
            this.dst = dst;
            m = 0;
            Arrays.fill(head, -1);
        }

        void addEdge(int u, int v, int c) {
            e[m] = new Edge(u, v, 0, c, head[u]);
            head[u] = m++;
            e[m] = new Edge(v, u, 0, 0, head[v]);
            head[v] = m++;
        }

        int maxFlow() {
            int ret = 0, delta;
            while(_bfs()) {
                System.arraycopy(head, 0, work, 0, n);
                while(true) {
                    delta = _dfs(src, INF);
                    if(delta == 0)
                        break;
                    ret += delta;
                }
            }
            return ret;
        }
    }

    static final int MAX = 12;
    static int n, t, zx, zy;
    static char[][] smp = new char[MAX][MAX], cmp = new char[MAX][MAX], work = new char[MAX][MAX];
    static int[][] vis = new int[MAX][MAX];
    static int[] dx = {1, 0, -1, 0};
    static int[] dy = {0, -1, 0, 1};

    static int X(int i, int j) { return i * n + j; }
    static int Y(int i, int j) { return n * n + i * n + j; }
    static int S() { return n * n * 2; }
    static int T() { return S() + 1; }
    static int N() { return T() + 1; }

    static class QNode {
        int x, y, t, type;
        QNode() {}
        QNode(int x, int y, int t, int type) {
            this.x = x; this.y = y; this.t = t; this.type = type;
        }
    }

    static void bfs(int sx, int sy, int[][] vis, char[][] work) {
        Queue<QNode> q = new LinkedList<>();
        q.offer(new QNode(sx, sy, 0, 0));
        vis[sx][sy] = 1;
        work[sx][sy] = work[sx][sy]; // no change
        q.offer(new QNode(zx, zy, 0, 1));
        while(!q.isEmpty()) {
            QNode u = q.poll();
            int nx, ny;
            if(u.t == t)
                break;
            if(u.type == 0 && Character.isLetter(work[u.x][u.y]))
                continue;
            for(int i = 0; i < 4; ++i) {
                nx = u.x + dx[i];
                ny = u.y + dy[i];
                if(nx >= 0 && nx < n && ny >= 0 && ny < n) {
                    if(u.type == 0 && vis[nx][ny] == 0 && !Character.isLetter(work[nx][ny])) {
                        vis[nx][ny] = 1;
                        q.offer(new QNode(nx, ny, u.t + 1, 0));
                    } else if(u.type == 1 && !Character.isLetter(work[nx][ny])) {
                        work[nx][ny] = 'Z';
                        q.offer(new QNode(nx, ny, u.t + 1, 1));
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        Dinic dinic = new Dinic();
        while(sc.hasNextInt()) {
            n = sc.nextInt();
            t = sc.nextInt();
            dinic.init(N(), S(), T());
            for(int i = 0; i < n; ++i) {
                String line = sc.next();
                smp[i] = line.toCharArray();
                for(int j = 0; j < n; ++j) {
                    if(Character.isDigit(smp[i][j]) && smp[i][j] > '0') {
                        dinic.addEdge(S(), X(i, j), smp[i][j] - '0');
                    } else if(smp[i][j] == 'Z') {
                        zx = i;
                        zy = j;
                    }
                }
            }
            for(int i=0; i < n; ++i) {
                String line = sc.next();
                cmp[i] = line.toCharArray();
                for(int j=0; j< n; ++j) {
                    if(Character.isDigit(cmp[i][j]) && cmp[i][j] > '0') {
                        dinic.addEdge(Y(i,j), T(), cmp[i][j] - '0');
                    }
                }
            }
            for(int i=0; i< n; ++i) {
                for(int j=0; j< n; ++j) {
                    if(!Character.isDigit(smp[i][j]) || smp[i][j] <= '0')
                        continue;
                    for(int xi=0; xi < n; ++xi)
                        Arrays.fill(vis[xi], 0);
                    for(int xi=0; xi< n; ++xi)
                        Arrays.fill(work[xi], (char)0);
                    bfs(i,j,vis,work);
                    for(int xi=0; xi< n; ++xi) {
                        for(int yi=0; yi< n; ++yi) {
                            if(!Character.isDigit(cmp[xi][yi]) || cmp[xi][yi] <= '0')
                                continue;
                            if(vis[xi][yi] != 0) {
                                dinic.addEdge(X(i,j), Y(xi, yi), INF);
                            }
                        }
                    }
                }
            }
            System.out.println(dinic.maxFlow());
        }
        sc.close();
    }
}
